interface ShippingStrategy {
  calculate(weight: number): number;
}
class GHNStrategy implements ShippingStrategy {
  calculate(weight: number) { return weight * 15000; }
}
const shippingStrategies: Record<string, ShippingStrategy> = {
  ghn: new GHNStrategy(),
};
export function getShippingFee(carrier: string, weight: number) {
  const strategy = shippingStrategies[carrier];
  if (!strategy) throw new Error('Unsupported carrier');
  return strategy.calculate(weight);
}

