class CachedExchangeRateService implements IExchangeRateService {
  constructor(private wrappee: IExchangeRateService, private cache: Cache) {}
  async getRate(cur: string) {
    if (await this.cache.has(cur)) return this.cache.get(cur);
    const rate = await this.wrappee.getRate(cur);
    await this.cache.set(cur, rate);
    return rate;
  }
}

