const orderTransitions: Record<OrderState, Partial<Record<OrderEvent, OrderState>>> = {
  PENDING: { PAY: 'PAID', CANCEL: 'CANCELLED' },
  PAID: { SHIP: 'SHIPPED', REFUND: 'REFUNDED' },
  SHIPPED: { COMPLETE: 'COMPLETED' },
};
function transition(current: OrderState, event: OrderEvent): OrderState {
  const next = orderTransitions[current]?.[event];
  if (!next) throw new Error(`Cannot ${event} from ${current}`);
  return next;
}

